import os
import sys
import urllib.parse

def load_config():
    api_key = os.getenv("API_KEY")
    db_password = os.getenv("DB_PASSWORD")

    if not api_key or not db_password:
        print("Error: Required environment variables API_KEY and DB_PASSWORD are missing.")
        sys.exit(1)

    return {
        "api_key": api_key,
        "db_password": db_password
    }

def validate_url(url):
    try:
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme in ['http', 'https']:
            return True
        return False
    except Exception:
        return False

def main():
    config = load_config()
    test_url = "https://example.com"

    if validate_url(test_url):
        print(f"URL {test_url} is valid.")
    else:
        print(f"URL {test_url} is invalid.")

if __name__ == "__main__":
    main()
